  'page.title': 'Produtos e saldos',
  'scene.base': 'Estoque',
  'scene.detalhe': 'Produto',
  'scene.cadastro': 'Novo produto',
  'scene.back': 'Voltar',
  'alertas.title': 'Abaixo do mínimo',
